import json
from datetime import datetime, timezone, timedelta

fpath = r'C:/Users/hzq00/.codex/sessions/2026/08/10/rollout-2026-08-10T16-32-17-019feacd-184e-7472-9f11-ea364c22e595.jsonl'
tz8 = timezone(timedelta(hours=8))
start = datetime(2026, 8, 14, 12, 0, 0, tzinfo=tz8)
end   = datetime(2026, 8, 14, 13, 0, 0, tzinfo=tz8)

results = []
with open(fpath, 'r', encoding='utf-8', errors='replace') as f:
    for lineno, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except:
            continue
        ts_raw = obj.get('timestamp') or obj.get('ts') or obj.get('created_at') or obj.get('time')
        if not ts_raw:
            for k in ('event','data','message','content'):
                sub = obj.get(k)
                if isinstance(sub, dict):
                    ts_raw = sub.get('timestamp') or sub.get('ts') or sub.get('created_at')
                    if ts_raw:
                        break
        if not ts_raw:
            continue
        try:
            if isinstance(ts_raw, (int,float)):
                dt = datetime.fromtimestamp(ts_raw, tz=timezone.utc).astimezone(tz8)
            else:
                s = str(ts_raw).replace('Z','+00:00')
                dt = datetime.fromisoformat(s).astimezone(tz8)
        except:
            continue
        if start <= dt < end:
            results.append((dt, obj, lineno))

print(f'匹配行数: {len(results)}')
for dt, obj, ln in results[:5]:
    print(f'  line {ln} @ {dt.isoformat()}  keys={list(obj.keys())[:8]}')

